class GF8:
    def __init__(self, val):
        self.val = val

    def __add__(self, other):
        return GF8(self.val ^ other.val)

    def __mul__(self, other):
        a = self.val
        b = other.val
        res = 0
        for i in range(3):
            if (b >> i) & 1:
                res ^= a
            # multiply a by x, reduce mod x^3 + x + 1
            a = a * 2
            if a & 8:
                a ^= 0b1011
        return GF8(res)

