class GF8:
    def __init__(self, val):
        self.val = val

    def __add__(self, other):
        return GF8(self.val ^ other.val)

    def __mul__(self, other):
        a = self.val
        b = other.val
        res = 0
        for i in range(3):
            if (b >> i) & 1:
                res ^= a
            # multiply a by x, reduce mod x^3 + x + 1
            a = a * 2
            if a & 8:
                a ^= 0b1011
        return GF8(res)

# Build the multiplication table as a lookup
mul_table = [[(GF8(i) * GF8(j)).val for j in range(8)] for i in range(8)]

def gf8_add(a, b):
    return a ^ b

def gf8_mul(a, b):
    return mul_table[a][b]

# Construct X and Y
n = 8
X = [[0]*n for _ in range(n)]
Y = [[0]*n for _ in range(n)]

for i in range(n):
    for j in range(n):
        X[i][j] = gf8_add(i, j)  # i XOR j
        Y[i][j] = gf8_add(i, gf8_mul(2, j))  # i XOR (2*j in GF(8))

# Verify X is Latin
print("X:")
for row in X:
    print(row)

print("\nY:")
for row in Y:
    print(row)

# Verify Latin property
print("\nVerifying X is Latin...")
for i in range(n):
    assert sorted(X[i]) == list(range(n)), f"Row {i} of X not a permutation"
    assert sorted([X[j][i] for j in range(n)]) == list(range(n)), f"Col {i} of X not a permutation"
print("X is Latin ✓")

print("\nVerifying Y is Latin...")
for i in range(n):
    assert sorted(Y[i]) == list(range(n)), f"Row {i} of Y not a permutation"
    assert sorted([Y[j][i] for j in range(n)]) == list(range(n)), f"Col {i} of Y not a permutation"
print("Y is Latin ✓")

# Verify orthogonality
print("\nVerifying orthogonality...")
pairs = set()
for i in range(n):
    for j in range(n):
        pairs.add((X[i][j], Y[i][j]))
assert len(pairs) == n*n, f"Only {len(pairs)} distinct pairs, expected {n*n}"
print(f"All {n*n} pairs are distinct ✓")

# Flatten and concatenate
solution = []
for i in range(n):
    for j in range(n):
        solution.append(X[i][j])
for i in range(n):
    for j in range(n):
        solution.append(Y[i][j])

print(f"\nSolution length: {len(solution)}")
print(solution)
